CREATE TABLE IF NOT EXISTS event_destinations (created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, event_destination_uuid uuid PRIMARY KEY, recurring_event_id TEXT NULL, destination TEXT NOT NULL, destination_point geography(Point,4326) NOT NULL, route_duration interval NOT NULL, route_information JSONB NOT NULL);
ALTER TABLE event_destinations ADD CONSTRAINT event_destinations_recurring_event_id_unique UNIQUE (recurring_event_id);
CREATE TABLE IF NOT EXISTS event_destination_links (event_uuid uuid PRIMARY KEY, event_destination_uuid uuid NOT NULL, created_at TIMESTAMP NOT NULL, CONSTRAINT fk_event_destination_links_event_destination_uuid__event_destin FOREIGN KEY (event_destination_uuid) REFERENCES event_destinations(event_destination_uuid) ON DELETE RESTRICT ON UPDATE RESTRICT);
